package com.collabspace.service; import lombok.RequiredArgsConstructor;import org.springframework.data.redis.core.StringRedisTemplate;import org.springframework.stereotype.Service;import java.time.Duration; @Service @RequiredArgsConstructor public class RateLimitService {private final StringRedisTemplate redis; public boolean allow(String key,int limit,int seconds){Long n=redis.opsForValue().increment("rl:"+key);if(n!=null&&n==1)redis.expire("rl:"+key,Duration.ofSeconds(seconds));return n==null||n<=limit;}}